// src/lib/mcp/tools/list-tips.ts
var list_tips_default = defineTool2({
  name: "list_tips",
  title: "Lista tips och r\xE5d",
  description: "Lista F\xF6ljis-appens tips och r\xE5d f\xF6r barn (morgon, skola, andning, social, fokus, kv\xE4ll, s\xF6mn, kropp). Filtrera p\xE5 kategori eller s\xF6kord.",
  inputSchema: {
    category: z.enum(["morgon", "skola", "andning", "social", "fokus", "kvall", "s\xF6mn", "kropp"]).optional().describe("Begr\xE4nsa till en kategori."),
    query: z.string().optional().describe("Fritexts\xF6kning i titel och text.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ category, query }) => {
    const q = query?.toLowerCase();
    const tips = TIPS.filter(
      (t) => (!category || t.category === category) && (!q || t.title.toLowerCase().includes(q) || t.body.toLowerCase().includes(q))
    ).map((t) => ({
      id: t.id,
      category: t.category,
      categoryLabel: TIP_CATEGORIES[t.category]?.label ?? t.category,
      title: t.title,
      body: t.body
    }));
    return {
      content: [
        {
          type: "text",
          text: tips.length ? tips.map((t) => `[${t.categoryLabel}] ${t.title}
${t.body}`).join("\n\n") : "Inga tips matchade s\xF6kningen."
        }
      ],
      structuredContent: { count: tips.length, tips }
    };
  }
});

