// src/lib/mcp/tools/list-shop-items.ts
var list_shop_items_default = defineTool4({
  name: "list_shop_items",
  title: "Lista aff\xE4rens sortiment",
  description: "Lista allt som g\xE5r att k\xF6pa med F\xF6ljispo\xE4ng i appens aff\xE4r: tillbeh\xF6r/kl\xE4der och bakgrunder, med pris.",
  inputSchema: {
    category: z2.enum(["accessory", "background"]).optional().describe("Begr\xE4nsa till tillbeh\xF6r eller bakgrunder."),
    maxPrice: z2.number().optional().describe("Visa bara saker som kostar h\xF6gst s\xE5 m\xE5nga F\xF6ljispo\xE4ng.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ category, maxPrice }) => {
    const labels = Object.fromEntries(SHOP_CATEGORIES.map((c) => [c.id, c.label]));
    const items = SHOP_ITEMS.filter(
      (i) => (!category || i.category === category) && (maxPrice == null || i.price <= maxPrice)
    ).map((i) => ({
      id: i.id,
      category: i.category,
      categoryLabel: labels[i.category] ?? i.category,
      name: i.name,
      description: i.description,
      price: i.price
    }));
    return {
      content: [
        {
          type: "text",
          text: items.length ? items.map((i) => `${i.name} (${i.categoryLabel}) \u2013 ${i.price} F\xF6ljispo\xE4ng: ${i.description}`).join("\n") : "Inget i aff\xE4ren matchade filtret."
        }
      ],
      structuredContent: { count: items.length, items }
    };
  }
});

