import { defineTool as defineTool5 } from "npm:@lovable.dev/mcp-js@0.28.0";
import { z as z3 } from "npm:zod@^4.4.3";
var feelings = FEELINGS.map((f) => f.value);
var suggest_coping_default = defineTool5({
  name: "suggest_coping",
  title: "F\xF6rslag utifr\xE5n k\xE4nsla",
  description: "Ge appens konkreta f\xF6rslag p\xE5 vad man kan g\xF6ra n\xE4r man k\xE4nner en viss k\xE4nsla (t.ex. stressad, ledsen, okoncentrerad).",
  inputSchema: {
    feeling: z3.enum(feelings).describe("K\xE4nslan som f\xF6rslagen ska matcha.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ feeling }) => {
    const suggestions = COPING_BY_FEELING[feeling] ?? [];
    return {
      content: [
        {
          type: "text",
          text: suggestions.length ? `N\xE4r man k\xE4nner sig ${feeling}:
- ${suggestions.join("\n- ")}` : `Inga f\xF6rslag finns f\xF6r k\xE4nslan ${feeling}.`
        }
      ],
      structuredContent: { feeling, suggestions }
    };
  }
});

